import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"基本用法 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置","slug":"配置","link":"#配置","children":[{"level":3,"title":"读写分离","slug":"读写分离","link":"#读写分离","children":[]}]},{"level":2,"title":"运行原生 SQL 查询","slug":"运行原生-sql-查询","link":"#运行原生-sql-查询","children":[{"level":4,"title":"运行 Select 查询","slug":"运行-select-查询","link":"#运行-select-查询","children":[]},{"level":4,"title":"使用命名绑定","slug":"使用命名绑定","link":"#使用命名绑定","children":[]},{"level":4,"title":"运行插入语句","slug":"运行插入语句","link":"#运行插入语句","children":[]},{"level":4,"title":"运行更新语句","slug":"运行更新语句","link":"#运行更新语句","children":[]},{"level":4,"title":"运行删除语句","slug":"运行删除语句","link":"#运行删除语句","children":[]},{"level":4,"title":"运行普通语句","slug":"运行普通语句","link":"#运行普通语句","children":[]}]},{"level":2,"title":"使用多个数据库连接","slug":"使用多个数据库连接","link":"#使用多个数据库连接","children":[]},{"level":2,"title":"数据库事务","slug":"数据库事务","link":"#数据库事务","children":[{"level":4,"title":"手动使用事务","slug":"手动使用事务","link":"#手动使用事务","children":[]}]},{"level":2,"title":"数据库事件","slug":"数据库事件","link":"#数据库事件","children":[{"level":3,"title":"查询记录","slug":"查询记录","link":"#查询记录","children":[]}]}],"relativePath":"2.x/zh-cn/database/basics.md","filePath":"2.x/zh-cn/database/basics.md"}'),u={name:"2.x/zh-cn/database/basics.md"};function d(k,a,g,h,v,f){const p=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[t(p),a[0]||(a[0]=s("h1",null,"基本用法",-1)),t(o),a[1]||(a[1]=s("p",null,[n("连接到数据库和运行Select是一个简单的过程，可以使用原始 SQL、"),s("a",{href:"./../database/query.html"},"查询生成器"),n(" 或 "),s("a",{href:"./../database/model.html"},"活动记录模型"),n(" 来支持。管理数据库表和填充种子数据由"),s("a",{href:"./../database/structure.html"},"迁移和播种"),n(" 处理。")],-1)),a[2]||(a[2]=s("p",null,[n("原始 SQL 和使用查询生成器将执行得更快，应该用于简单任务。 Active Record 是流行框架 Ruby On Rails 使用的一种方法。它允许一个简单的界面来执行重复性任务，例如创建、读取、更新和删除数据库记录。您可以了解更多关于 "),s("a",{href:"http://en.wikipedia.org/wiki/Active_record_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Wikipedia 上的活动记录模式"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n("。")],-1)),a[3]||(a[3]=r(`<h2 id="配置"><a href="#配置" class="header-anchor">#</a> 配置</h2><p>应用程序的数据库配置位于 <code>config/database.php</code> 文件中。在此文件中，您可以定义所有数据库连接，并指定默认情况下应使用哪个连接。此文件中提供了所有受支持的数据库系统的示例。</p><h3 id="读写分离"><a href="#读写分离" class="header-anchor">#</a> 读写分离</h3><p>有时候你希望 SELECT 语句使用一个数据库连接，而 INSERT，UPDATE，和 DELETE 语句使用另一个数据库连接。在 Laravel 中，无论你是使用原生查询，查询构造器，或者是 Eloquent ORM，都能轻松的实现</p><p>为了弄明白读写分离是如何配置的，我们先来看个例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;read&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;192.168.1.1&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;write&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;196.168.1.2&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mysql&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;database&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;database&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;username&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;root&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;charset&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;collation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8_unicode_ci&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;prefix&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>注意在以上的例子中，配置数组中增加了三个键，分别是 <code>read</code>， <code>write</code> 和 <code>sticky</code>。 <code>read</code> 和 <code>write</code> 的键都包含一个键为 <code>host</code> 的数组。而 <code>read</code> 和 <code>write</code> 的其他数据库都在键为 <code>mysql</code> 的数组中。</p><p>如果你想重写主数组中的配置，只需要修改 <code>read</code> 和 <code>write</code> 数组即可。所以，这个例子中： <code>192.168.1.1</code>和<code>192.168.1.2</code> 将作为 「读」 连接主机，而 <code>192.168.1.3</code> 将作为 「写」 连接主机。这两个连接会共享 <code>mysql</code> 数组的各项配置，如数据库的凭据(用户名 / 密码)，前缀，字符编码等。</p><p><a id="oc-running-raw-sql-queries"></a></p><h2 id="运行原生-sql-查询"><a href="#运行原生-sql-查询" class="header-anchor">#</a> 运行原生 SQL 查询</h2><p>一旦配置好数据库连接后，便可以使用 <code>DB</code> facade 运行查询。 <code>DB</code> facade 为每种类型的查询提供了方法： <code>select</code>，<code>update</code>，<code>insert</code>，<code>delete</code> 和 <code>statement</code>。</p><h4 id="运行-select-查询"><a href="#运行-select-查询" class="header-anchor">#</a> 运行 Select 查询</h4><p>你可以使用 <code>DB</code> 门面 的 <code>select</code> 方法来运行基础的查询语句：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where active = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>传递给 <code>select</code> 方法的第一个参数就是一个原生的 SQL 查询，而第二个参数则是需要绑定到查询中的参数值。通常，这些值用于约束 <code>where</code> 语句。参数绑定用于防止 SQL 注入。</p><p><code>select</code> 方法将始终返回一个数组，数组中的每个结果都是一个 <code>StdClass</code> 对象，可以像下面这样访问结果值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="使用命名绑定"><a href="#使用命名绑定" class="header-anchor">#</a> 使用命名绑定</h4><p>除了使用 <code>?</code> 表示参数绑定外，你也可以使用命名绑定来执行一个查询：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where id = :id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="运行插入语句"><a href="#运行插入语句" class="header-anchor">#</a> 运行插入语句</h4><p>可以使用 <code>DB</code> 门面 的 <code>insert</code> 方法来执行 <code>insert</code> 语句。与 <code>select</code> 一样，该方法将原生 SQL 查询作为其第一个参数，并将绑定数据作为第二个参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;insert into users (id, name) values (?, ?)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="运行更新语句"><a href="#运行更新语句" class="header-anchor">#</a> 运行更新语句</h4><p><code>update</code> 方法用于更新数据库中现有的记录。该方法返回受该语句影响的行数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;update users set votes = 100 where name = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="运行删除语句"><a href="#运行删除语句" class="header-anchor">#</a> 运行删除语句</h4><p><code>delete</code> 方法用于从数据库中删除记录。与 <code>update</code> 一样，返回受该语句影响的行数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deleted</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;delete from users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="运行普通语句"><a href="#运行普通语句" class="header-anchor">#</a> 运行普通语句</h4><p>有些数据库语句不会有任何返回值。对于这些语句，你可以使用 <code>DB</code> Facade 的 <code>statement</code> 方法来运行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">statement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;drop table users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-multiple-database-connections"></a></p><h2 id="使用多个数据库连接"><a href="#使用多个数据库连接" class="header-anchor">#</a> 使用多个数据库连接</h2><p>当使用多个数据库连接时，你可以通过 <code>DB</code> Facade 的 <code>connection</code> 方法访问每一个连接。传递给 <code>connection</code>方法的参数 <code>name</code> 应该是 <code>config/database.php</code> 配置文件中 connections 数组中的一个值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以使用一个连接实例上的 <code>getPdo</code> 方法访问底层的 PDO 实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pdo</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getPdo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="数据库事务"><a href="#数据库事务" class="header-anchor">#</a> 数据库事务</h2><p>你可以使用 <code>DB</code> 门面的 <code>transaction</code> 方法在数据库事务中运行一组操作。如果事务的闭包 <code>Closure</code> 中出现一个异常，事务将会回滚。如果事务闭包 <code>Closure</code> 执行成功，事务将自动提交。一旦你使用了 <code>transaction</code> ， 就不再需要担心手动回滚或提交的问题：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">transaction</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="手动使用事务"><a href="#手动使用事务" class="header-anchor">#</a> 手动使用事务</h4><p>如果你想要手动开始一个事务，并且对回滚和提交能够完全控制，那么你可以使用 <code>DB</code> 门面的 <code>beginTransaction</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">beginTransaction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你可以使用 <code>rollBack</code> 方法回滚事务：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">rollBack</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>最后，你可以使用 <code>commit</code> 方法提交事务：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：使用 <code>Db</code> 门面的事务方法还可以控制 <a href="./../database/query.html">查询构建器</a> 和 <a href="./../database/model.html">模型查询</a> 的事务。</p></blockquote><h2 id="数据库事件"><a href="#数据库事件" class="header-anchor">#</a> 数据库事件</h2><p>如果你想监控程序执行的每一个 SQL 查询，你可以使用 <code>listen</code> 方法。这个方法对于记录查询或调试非常有用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$sql</span><span class="token punctuation">,</span> <span class="token variable">$bindings</span><span class="token punctuation">,</span> <span class="token variable">$time</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>就像 <a href="./../services/events.html#oc-where-to-register-listeners">事件注册</a>一样，您可以在 <a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a> 的 <code>boot</code> 方法中注册查询侦听器。 或者，可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用它来放置此逻辑。</p><h3 id="查询记录"><a href="#查询记录" class="header-anchor">#</a> 查询记录</h3><p>启用查询日志记录后，会在内存中保存为当前请求运行的所有查询的日志。 调用 <code>enableQueryLog</code> 方法启用此功能。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">enableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要获取已执行查询的数组，您可以使用 <code>getQueryLog</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$queries</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">getQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>但是，在某些情况下，例如在插入大量行时，这可能会导致应用程序使用过多的内存。 要禁用日志，您可以使用 <code>disableQueryLog</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">disableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：为了更快地调试，调用 <code>trace_sql</code> <a href="./../services/error-log.html#oc-helper-functions">助手函数</a> 可能更有用。</p></blockquote>`,61))])}const q=c(u,[["render",d]]);export{m as __pageData,q as default};
